output_text:
[
  {
    "id": "cart_required_for_items",
    "text": "A shopper is prohibited from picking up shelf items unless they are currently using a cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_pickup_without_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper is prohibited from carrying merchandise by hand rather than placing it in a cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "must_take_entry_cart",
    "text": "Before leaving the store, a shopper is obliged to take the cart stationed at the entry cart point.",
    "abstraction": {
      "state_properties": {
        "entry_cart_point": "at(1,5)"
      },
      "events": {
        "take_entry_cart": {
          "pre": {
            "and": [
              "entry_cart_point",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entry_cart"
    }
  },
  {
    "id": "return_cart_after_item",
    "text": "After collecting any item while using a cart, the shopper is obliged to return the cart to the return bay.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)"
      },
      "events": {
        "take_item_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "hasCart",
              "return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_item_with_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper is prohibited from exiting the store while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "currently_using_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "currently_using_cart"
        ]
      }
    }
  },
  {
    "id": "leave_cart_only_return_bay",
    "text": "A shopper is prohibited from putting down a cart anywhere except the designated return bay.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "not_at_return_bay": {
          "not": "return_bay"
        }
      },
      "events": {
        "leave_cart_outside_return_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "not_at_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return_bay"
    }
  },
  {
    "id": "cart_free_exit_corridor",
    "text": "Carts are prohibited in the lower checkout and exit corridor, so shoppers must traverse that corridor without a cart.",
    "abstraction": {
      "state_properties": {
        "exit_corridor": {
          "or": [
            "at(2,4)",
            "at(3,4)",
            "at(4,4)",
            "at(5,4)",
            "at(6,4)",
            "at(7,4)",
            "at(8,4)",
            "at(9,4)",
            "at(0,5)",
            "at(2,5)",
            "at(3,5)",
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_in_exit_corridor": {
          "and": [
            "hasCart",
            "exit_corridor"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_exit_corridor"
    }
  },
  {
    "id": "taken_cart_must_be_used",
    "text": "Once a shopper takes a cart, they are obliged to use that cart to collect at least one required item.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "collect_item_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "collect_item_with_cart"
    }
  }
]
